insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('aa56dc0d-4b9f-41bf-ac1d-623f30e51b65', '3715f748-7f2c-43e2-94e2-24659f40ae2d', $$inleiding: restaurant La Mama met all-inclusive diner, adviseur maakt kosten- en opbrengstenschatting$$,
   $$economie-havo-2017-i-restaurant-la-mama-context1.png$$,
   $$Georgio en zijn vrouw Teresia zijn sinds kort de eigenaren van restaurant La Mama. Het restaurant wordt momenteel verbouwd en zal over een paar weken opengaan. Georgio en Teresia hopen zo hun droomwens in vervulling te laten gaan. Ze willen van La Mama een uniek restaurant maken, zeven dagen per week open met een aanbod van uitsluitend een all-inclusive diner: een viergangenmenu inclusief drank voor een vaste prijs. Ze hebben een adviseur gevraagd een inschatting te maken van de kosten en opbrengsten na opening (zie bron 1). Op een avond bespreken Georgio en Teresia bij kaarslicht de bedrijfsdoelstelling van La Mama.$$, 'inline'),
  ('e7a0e6b7-e80d-4ea5-87a1-171e6a17753d', '3715f748-7f2c-43e2-94e2-24659f40ae2d', $$tekstwolken Georgio (break-even, zoveel mogelijk klanten) en Teresia (maximale totale omzet)$$,
   $$economie-havo-2017-i-restaurant-la-mama-context2.png$$,
   $$Georgio: Ik wil dat La Mama in ieder geval elke avond break-even draait en ook zoveel mogelijk klanten trekt.
Teresia: We moeten meteen vanaf het begin streven naar maximale totale omzet per avond.$$, 'inline'),
  ('7997abfe-4e5b-4dfd-92bc-827b899c8040', '3715f748-7f2c-43e2-94e2-24659f40ae2d', $$prijs € 50, op maandag € 40; Georgio gaat uit van prijselastische vraag$$,
   $$economie-havo-2017-i-restaurant-la-mama-context3.png$$,
   $$Uiteindelijk stellen Georgio en Teresia de prijs voor een all-inclusive diner vast op € 50. Omdat Georgio verwacht dat het restaurantbezoek op maandag beduidend lager zal zijn dan de rest van de week, stelt hij voor de prijs op maandag te verlagen naar € 40. Georgio motiveert: “Ik ga er daarbij van uit dat we te maken hebben met een prijselastische vraag.”$$, 'inline'),
  ('20bf985c-6305-4e22-9636-407048df44fe', '3715f748-7f2c-43e2-94e2-24659f40ae2d', $$Teresia: op maandag ligt de prijs-afzetlijn anders$$,
   $$economie-havo-2017-i-restaurant-la-mama-context4.png$$,
   $$Teresia reageert: “Je maakt een fout. Deze grafiek geldt niet voor een maandag, want op die dag ligt de prijs-afzetlijn anders dan de andere dagen van de week.”$$, 'inline'),
  ('2e6ee17c-7e2c-49e5-97ea-69affce66c91', '3715f748-7f2c-43e2-94e2-24659f40ae2d', $$verbouwing van € 100.000: hypothecaire lening of crowdfunding$$,
   $$economie-havo-2017-i-restaurant-la-mama-context5.png$$,
   $$Een jaar na de opening ervaren Georgio en Teresia dat ze in de grote eetzaal niet goed de huiselijke sfeer kunnen krijgen die ze eigenlijk zoeken. Ze besluiten tot een verbouwing. Dit gaat hen € 100.000 kosten en zoveel geld hebben ze op dit moment niet. Ze kunnen naar de bank gaan om een extra hypothecaire lening af te sluiten, of ze kunnen kiezen voor lenen via het systeem van crowdfunding, een moderne manier van financieren waarover Teresia gelezen heeft (bron 3). In een schema zetten ze twee aspecten van beide financieringsvormen onder elkaar.$$, 'inline'),
  ('9ca251dc-c80a-457b-8376-920f8342f5fa', '3715f748-7f2c-43e2-94e2-24659f40ae2d', $$bron 1: verwachte kosten en opbrengsten per avond (GTK, MK, MO, P = GO)$$,
   $$economie-havo-2017-i-restaurant-la-mama-context6.png$$,
   $$bron 1 verwachte kosten en opbrengsten per avond van La Mama
grafiek met € (0-140) tegen aantal all-inclusive diners per avond (0-120), met de lijnen GTK, MK, MO en P = GO
GTK = gemiddelde totale kosten
P = verkoopprijs
GO = gemiddelde opbrengst
P = GO = prijs-afzetlijn
MO = marginale opbrengsten
MK = marginale kosten$$, 'inline'),
  ('bec0420e-f4ce-4eb8-a07c-6f06a670bbc8', '3715f748-7f2c-43e2-94e2-24659f40ae2d', $$bron 2: keuzemogelijkheden bij vraag 3 (grafiek 1 t/m 4)$$,
   $$economie-havo-2017-i-restaurant-la-mama-context7.png$$,
   $$bron 2 keuzemogelijkheden bij vraag 3
grafiek 1, grafiek 2, grafiek 3 en grafiek 4: telkens de grafiek uit bron 1 (GTK, MK, MO, P = GO) met een ander gearceerd vlak$$, 'inline'),
  ('300df393-2497-44a6-8229-0bef8eca26c3', '3715f748-7f2c-43e2-94e2-24659f40ae2d', $$bron 3: financiering door middel van crowdfunding$$,
   $$economie-havo-2017-i-restaurant-la-mama-context8.png$$,
   $$bron 3 financiering door middel van crowdfunding
Crowdfunding is een manier om een investeringsproject te financieren, waarbij veel mensen elk een klein bedrag kunnen beleggen. Crowdfunding is laagdrempelig, met direct contact tussen belegger en ondernemer, en kan plaatsvinden zonder financiële tussenpersonen. De kredietnemer betaalt aan de kredietverlener een vergoeding die afhankelijk is van het succes van het investeringsproject.$$, 'inline'),
  ('1b2d7578-1c7d-48e2-a932-e28e4bb9ccf5', 'a7343ca1-a440-4d92-af74-d5469d797453', $$uit een krant (maart 2014): inkomensongelijkheid leidt via onrust tot een lager nationaal inkomen$$,
   $$economie-havo-2017-i-hoe-verdelen-context1.png$$,
   $$uit een krant (maart 2014): Een meerderheid van de economen is bezorgd over de toenemende inkomensverschillen in Nederland. Volgens deze economen leidt groeiende inkomensongelijkheid tot maatschappelijke onrust, die daarna via conjuncturele en structurele ontwikkelingen tot een lager nationaal inkomen kan leiden. Econoom Jakobson: “Om die reden kan het verstandig zijn om inkomen te herverdelen. De vraag is dan: wat is de meest efficiënte maatregel?”$$, 'inline'),
  ('7f09a5fb-759a-4e60-a8de-d9b5b8f02971', 'a7343ca1-a440-4d92-af74-d5469d797453', $$herverdelingsmaatregelen: minimumloon en hoogste tarief inkomstenbelasting verhogen$$,
   $$economie-havo-2017-i-hoe-verdelen-context2.png$$,
   $$Veelgebruikte herverdelingsmaatregelen zijn het verhogen van het minimumloon en het verhogen van het hoogste tarief van de inkomstenbelasting.$$, 'inline'),
  ('6d497f7b-2206-4035-9237-0525a8838180', 'a7343ca1-a440-4d92-af74-d5469d797453', $$interview met econoom Jakobson: begin van het artikel$$,
   $$economie-havo-2017-i-hoe-verdelen-context3.png$$,
   $$Volgens econoom Jakobson zijn beide maatregelen geen efficiënte manieren om het inkomen te herverdelen. Stel je de volgende situatie voor. Als journalist neem jij een interview af bij Jakobsen over dit onderwerp. Op basis van jouw aantekeningen (bron 2) schrijf je een artikel. Dat artikel begint als volgt: “Volgens econoom Jakobson leidt het verhogen van het hoogste tarief van de inkomstenbelasting tot een lager nationaal inkomen en leidt het verhogen van het minimumloon tot hogere werkloosheid onder uitgerekend die werknemers, voor wie de bescherming met het minimumloon bedoeld is. Jakobson stelt dat een verhoging van de arbeidskorting voor de laagstbetaalden efficiënter is. Eén en ander laat zich als volgt toelichten….”$$, 'inline'),
  ('040fd4c2-e7a1-46c1-bf74-ad61fa15b44e', 'a7343ca1-a440-4d92-af74-d5469d797453', $$bron 1: oorzaak-gevolgschema (conjuncturele en structurele ontwikkeling)$$,
   $$economie-havo-2017-i-hoe-verdelen-context4.png$$,
   $$bron 1 oorzaak-gevolgschema
maatschappelijke onrust → conjuncturele ontwikkeling: ...(a)... → ...(b)... → ...(c)... → lager nationaal inkomen
maatschappelijke onrust → structurele ontwikkeling: ...(d)... → particuliere investeringen dalen → ...(e)... → lager nationaal inkomen
(particuliere investeringen dalen wijst ook naar ...(c)...)$$, 'inline'),
  ('b94d8239-7454-4624-b497-c91d9694abe0', 'a7343ca1-a440-4d92-af74-d5469d797453', $$bron 2: aantekeningen interview$$,
   $$economie-havo-2017-i-hoe-verdelen-context5.png$$,
   $$bron 2 aantekeningen interview
herverdelingsmaatregelen: verhogen hoogste tarief inkomstenbelasting; verhogen minimumloon; verhoging arbeidskorting laagstbetaalden
verhogen hoogste tarief inkomstenbelasting → lager nationaal inkomen → inkomensnivellering
verhogen minimumloon → meer werkloosheid → lager nationaal inkomen; verhogen minimumloon → inkomensnivellering
verhoging arbeidskorting laagstbetaalden → (groot effect) → inkomensnivellering$$, 'inline'),
  ('fd885b69-b42f-4937-abf4-7b6a7d491649', '7d0695ba-0322-4099-bbb6-a9c838cd3b02', $$uit een krant (mei 2013): koers Turkse lira gedaald door krimp eurozone$$,
   $$economie-havo-2017-i-liever-geen-lira-context1.png$$,
   $$uit een krant (mei 2013): Turkije is een belangrijke handelspartner van de eurozone. De Turkse export heeft de afgelopen jaren dan ook veel hinder ondervonden van de economische krimp in de landen van de eurozone, met als gevolg dat de koers van de Turkse lira ten opzichte van de euro is gedaald.$$, 'inline'),
  ('9020a189-3c20-47b4-b41b-3b6e10aefea0', '7d0695ba-0322-4099-bbb6-a9c838cd3b02', $$Bilal wisselt op 1 mei 2013 euro's om voor een appartement van 200.000 lira$$,
   $$economie-havo-2017-i-liever-geen-lira-context2.png$$,
   $$Bilal besluit op 1 mei 2013, na meer dan veertig jaren werken in Nederland, terug te keren naar zijn vaderland Turkije. Van zijn spaargeld in Nederland wil hij een appartement van 200.000 Turkse lira kopen aan de westkust. De sleuteloverdracht van het appartement is op 1 september 2013. Op die datum vindt ook de betaling plaats. Toch besluit hij al op
1 mei 2013 euro’s om te wisselen in de benodigde 200.000 Turkse lira.$$, 'inline'),
  ('532960da-663f-45fb-92db-d106421420c2', '7d0695ba-0322-4099-bbb6-a9c838cd3b02', $$uit een krant (2 september 2013): Turkse Centrale Bank wisselt 6 miljard dollar om in lira's$$,
   $$economie-havo-2017-i-liever-geen-lira-context3.png$$,
   $$uit een krant (2 september 2013): De Turkse Centrale Bank (TCB) heeft gisteren op de valutamarkt een bedrag van 6 miljard Amerikaanse dollars omgewisseld in Turkse lira’s. Deze maatregel werd genomen met het oog op de inflatie in Turkije, die door de koersdaling van de lira is opgelopen naar ruim 6%. De TCB hoopt met haar maatregel verdere koersdaling van de Turkse munteenheid tegen te gaan.$$, 'inline'),
  ('460b1a45-acf6-44f6-93c6-263525472599', '7d0695ba-0322-4099-bbb6-a9c838cd3b02', $$bron 1: koers US dollar in Turkse lira en koers euro in US dollar (mei-september 2013)$$,
   $$economie-havo-2017-i-liever-geen-lira-context4.png$$,
   $$bron 1 koers US dollar in Turkse lira en koers euro in US dollar (1 mei – 1 september 2013)
koers dollar in Turkse lira: 1 mei 1,79; 1 jun 1,90; 1 jul 1,94; 1 aug 1,95; 1 sep 2,05
koers euro in dollar: 1 mei 1,29; 1 jun 1,29; 1 jul 1,28; 1 aug 1,33; 1 sep 1,32$$, 'inline'),
  ('2f9ef57f-f31d-4edd-8245-3b98f5b16132', '7d0695ba-0322-4099-bbb6-a9c838cd3b02', $$bron 2: valuta-interventie Turkse Centrale Bank (grafiek 1 t/m 4)$$,
   $$economie-havo-2017-i-liever-geen-lira-context5.png$$,
   $$bron 2 valuta-interventie Turkse Centrale Bank op 1 september 2013
grafiek 1: koers dollar in Turkse lira (aantal dollars x miljard)
grafiek 2: koers Turkse lira in dollar (aantal lira''s x miljard)
grafiek 3: koers dollar in Turkse lira (aantal dollars x miljard)
grafiek 4: koers Turkse lira in dollar (aantal lira''s x miljard)
V en A1 = vraag en aanbod vóór valuta-interventie
V en A2 = vraag en aanbod na valuta-interventie$$, 'inline'),
  ('ff655d6d-fca1-422d-9734-3d6de86dfe81', '078336c8-7d6e-478e-b506-81b140fb5749', $$uit een krant (augustus 2014): ECB wil inflatie net onder 2% houden; loon-prijsspiraal en deflatie$$,
   $$economie-havo-2017-i-dreigende-deflatie-context1.png$$,
   $$uit een krant, augustus 2014: Normaal gesproken wordt het leven almaar duurder. Een beetje inflatie wordt gezien als smeerolie voor de economie: zij verleidt mensen om aankopen te doen in de verwachting dat spullen morgen een tikje duurder zijn. Door middel van rentebeleid probeert de Europese Centrale Bank (ECB) de inflatie net onder de 2% te houden. De inflatie mag volgens de ECB niet te hoog zijn, omdat er dan een loon-prijsspiraal kan ontstaan. Te lage inflatie kan omslaan in deflatie, die de economische groei kan schaden.$$, 'inline'),
  ('597b127d-c56e-4ffe-b903-035fe32236c8', '078336c8-7d6e-478e-b506-81b140fb5749', $$loon-prijsspiraal: belang 1 werknemers (koopkracht) en belang 2 werkgevers (winst)$$,
   $$economie-havo-2017-i-dreigende-deflatie-context2.png$$,
   $$Een loon-prijsspiraal kan ontstaan indien loonstijgingen en prijsstijgingen elkaar versterken als gevolg van de onderstaande belangen: belang 1: werknemers willen koopkracht behouden; belang 2: werkgevers willen winst behouden.$$, 'inline'),
  ('71646835-14a1-495a-9623-8456e18fedca', '078336c8-7d6e-478e-b506-81b140fb5749', $$eurozone-deflatie-index meet deflatierisico (zie bron 2)$$,
   $$economie-havo-2017-i-dreigende-deflatie-context3.png$$,
   $$Iedere maand wordt er een ‘eurozone-deflatie-index’ gepubliceerd (zie bron 2). In deze graadmeter worden eurolanden gescoord op het deflatierisico.$$, 'inline'),
  ('abd38a03-f19f-445f-a7b6-eb61e42e776f', '078336c8-7d6e-478e-b506-81b140fb5749', $$bron 1: loon-prijsspiraal (hoge inflatie, hoge lonen, a en b)$$,
   $$economie-havo-2017-i-dreigende-deflatie-context4.png$$,
   $$bron 1 loon-prijsspiraal
hoge inflatie → (b) → hoge lonen → (a) → hoge inflatie$$, 'inline'),
  ('8821c3f6-f912-4f4e-888b-6ff657455e8a', '078336c8-7d6e-478e-b506-81b140fb5749', $$bron 2: eurozone-deflatie-index juli en augustus 2014$$,
   $$economie-havo-2017-i-dreigende-deflatie-context5.png$$,
   $$bron 2 eurozone-deflatie-index juli en augustus 2014
deflatie-index | juli | aug
eurozone | −6 | −6
Duitsland | −1 | −1
Oostenrijk | −2 | −2
België | −3 | −3
Ierland | −5 | −4
Finland | −4 | −4
Frankrijk | −6 | −6
Spanje | −6 | −6
Nederland | −8 | −6
Italië | −6 | −7
Portugal | −6 | −7
Griekenland | −7 | −7
Een score van −10 betekent het hoogste deflatierisico.$$, 'inline'),
  ('052ddb83-c077-440b-8e59-71e3a0f4bc30', '078336c8-7d6e-478e-b506-81b140fb5749', $$bron 3: model van de economie van de eurozone (pijlen 1 t/m 14)$$,
   $$economie-havo-2017-i-dreigende-deflatie-context6.png$$,
   $$bron 3 model van de economie van de eurozone
schema met de blokken rentebeleid ECB, koers euro, prijspeil eurozone, concurrentiepositie eurozone, export - import, bestedingen eurozone, werkloosheid eurozone en loonkosten, verbonden door genummerde pijlen 1 t/m 14$$, 'inline'),
  ('18b416c6-8677-4e45-aaf5-8219897eb5aa', 'f3f0df5e-c3a8-40f4-8e6a-c4ba34388309', $$inleiding: Europlane wil cao-loonsverhoging terugdraaien naar 0%; loonsverhoging 0,8%, inflatie 2,75%$$,
   $$economie-havo-2017-i-uitgestelde-vluchten-context1.png$$,
   $$Luchtvaartmaatschappij Europlane concurreert op de prijs van vluchten binnen Europa. Vanwege sterke prijsdruk op deze vluchten wil de directie van Europlane de huidige collectieve arbeidsovereenkomst (cao), die nog één jaar loopt, tussentijds aanpassen door de afgesproken loonsverhoging terug te draaien naar 0%. De vakbond, waarbij twee derde van de werknemers is aangesloten, is daar op tegen. Volgens de vakbond is er in de huidige cao een loonsverhoging van slechts 0,8% afgesproken, terwijl de inflatie 2,75% bedraagt. Bovendien stelt de woordvoerder van de vakbond: “Afspraak is afspraak. De vakbondsleden hebben er hard voor gevochten!”$$, 'inline'),
  ('616cf3a2-05e3-4e1f-8453-c58efb6d5a0b', 'f3f0df5e-c3a8-40f4-8e6a-c4ba34388309', $$discussie tussen vakbond en directie over tussentijds aanpassen van de cao (tekstballonnen)$$,
   $$economie-havo-2017-i-uitgestelde-vluchten-context2.png$$,
   $$De vakbond en de directie van Europlane discussiëren over het tussentijds aanpassen van de cao:
vakbond: Een gelijkblijvend loon is niet acceptabel voor de werknemers. Als gevolg van prijsverlaging is de afzet met 20% gestegen, terwijl de totale kosten met 10% zijn gedaald.
directie: Maar als gevolg van forse concurrentie zijn de totale opbrengsten ook met 10% gedaald en hebben we slechts break-even gedraaid, net als vorig jaar.$$, 'inline'),
  ('282f9f9c-604e-480d-9ca2-dc4353ba3f5d', 'f3f0df5e-c3a8-40f4-8e6a-c4ba34388309', $$cao niet aangepast; econoom: beide partijen belanden in een gevangenendilemma$$,
   $$economie-havo-2017-i-uitgestelde-vluchten-context3.png$$,
   $$Uiteindelijk wordt besloten de cao niet tussentijds aan te passen. Ondertussen gaan de partijen zich bezinnen over de koers van de cao voor het volgend jaar. Elke partij heeft twee keuzemogelijkheden wat betreft de eigen opstelling tegenover de andere partij. Een econoom brengt de situatie in kaart en toont de mogelijke consequenties van elke keuze (bron 1). Hij stelt: “Indien beide partijen hun dominante strategie volgen, belanden ze in een gevangenendilemma.”$$, 'inline'),
  ('e1bcab46-15b0-4d0f-bab1-f5614da8b8d0', 'f3f0df5e-c3a8-40f4-8e6a-c4ba34388309', $$bron 1: consequenties voor directie en vakbond van keuzemogelijkheden (smileymatrix)$$,
   $$economie-havo-2017-i-uitgestelde-vluchten-context4.png$$,
   $$bron 1 consequenties voor directie en vakbond van keuzemogelijkheden ten aanzien van een nieuwe cao (directie ; vakbond)
directie (werkgever) \ vakbond (werknemers) | toegeven (inbinden) | vasthouden aan hoge eisen
toegeven (inbinden) | ☺ ; ☺ | ☹☹ ; ☺☺
vasthouden aan een laag bod | ☺☺ ; ☹☹ | ☹ ; ☹
Toelichting
De smiley’s ter linkerzijde van de puntkomma geven steeds de consequenties van de ontstane situatie voor de directie, die ter rechterzijde van de puntkomma de consequenties voor de vakbond:
☺☺ zeer gunstig
☺ enigszins gunstig
☹ enigszins ongunstig
☹☹ zeer ongunstig$$, 'inline'),
  ('52d3cd6a-571c-4dff-b3e6-66a5fcec6271', '7c426542-26d2-4662-869f-bdac3c43b795', $$inleiding: fietsverzekeraar FAM verzamelt kengetallen over e-bikes (2013 en 2014)$$,
   $$economie-havo-2017-i-e-bike-steeds-populairder-ook-bij-dieven-context1.png$$,
   $$Fietsassurantiemaatschappij FAM, marktleider op het gebied van fietsdiefstalverzekeringen, heeft in een onderzoek een aantal kengetallen over 2013 verzameld. In het oog springt de toenemende populariteit van e-bikes. Op basis van deze ontwikkeling heeft FAM ook een aantal verwachte kengetallen voor het jaar 2014 opgenomen in het onderzoeksrapport. De gegevens staan vermeld in bron 1.$$, 'inline'),
  ('baa76f4b-b881-4a45-890e-d512b64d8b2a', '7c426542-26d2-4662-869f-bdac3c43b795', $$directievergadering FAM: hogere uniforme premie, averechtse selectie, premiedifferentiatie$$,
   $$economie-havo-2017-i-e-bike-steeds-populairder-ook-bij-dieven-context2.png$$,
   $$In de directievergadering van FAM wordt het onderzoeksrapport besproken. Er zijn verschillende opvattingen over hoe FAM moet reageren op de verwachte toename van e-bikediefstal.
− De financieel directeur wil voor 2014 een hogere premie vaststellen waarbij de opslag voor bedrijfskosten en winst in euro’s per polis hetzelfde blijft als in 2013.
− De algemeen directeur stelt dat zo’n uniforme premieverhoging zal leiden tot averechtse selectie, met als gevolg dat de totale winst in 2014 kan dalen.
− De marketingmanager stelt daarom voor om premiedifferentiatie toe te passen, zodat averechtse selectie voorkomen kan worden.$$, 'inline'),
  ('55c395a4-e70e-406f-9f7c-98c1fe8b69ec', '7c426542-26d2-4662-869f-bdac3c43b795', $$bron 1: enkele resultaten uit het onderzoeksrapport van FAM (tabel 2013 en 2014)$$,
   $$economie-havo-2017-i-e-bike-steeds-populairder-ook-bij-dieven-context3.png$$,
   $$bron 1 enkele resultaten uit het onderzoeksrapport van FAM
